-- Hub sheet in the words of a Chilean bike mechanic (2026-09-17).
-- Relabels the hub definitions by key and replaces the hub contract helpers
-- with one plain explanation per field. Facts, values, option labels, rules
-- and flags are untouched; the revision trigger bumps the contract_version.
-- Rerunnable: every update is conditional on the old wording.
-- Generated by scripts/inventory/compile_hub_plain_language.py --version 20260917210000.
begin;
set local lock_timeout='5s';
set local statement_timeout='120s';
do $guard$ begin
 if (select count(*) from public.spec_definitions where tenant_id is null and key in ('spec_evidence_source','hub_old_mm','spoke_hole_count','hub_spoke_head_interface','bearing_system','rotor_mount_type','hub_drive_receiver_present','hub_drive_receiver_kind','hub_drive_receiver_reference','flange_pcd_left_mm','flange_pcd_right_mm','center_to_flange_left_mm','center_to_flange_right_mm','hub_flange_to_flange_mm','spoke_hole_diameter_mm','hub_axle_diameter_datum','hub_supplied_thru_axle_reference','hub_package_pieces')) <> 18 then
  raise exception 'A relabeled definition is missing among the global definitions';
 end if;
 if (select count(*) from public.spec_templates where tenant_id is null and key='hub') <> 1 then
  raise exception 'The global hub template is missing';
 end if;
end $guard$;
update public.spec_definitions set label='Fuente del dato', updated_at=now() where tenant_id is null and key='spec_evidence_source' and label is distinct from 'Fuente del dato';
update public.spec_definitions set label='Ancho entre tuercas (OLD)', updated_at=now() where tenant_id is null and key='hub_old_mm' and label is distinct from 'Ancho entre tuercas (OLD)';
update public.spec_definitions set label='Cantidad de hoyos (rayos)', updated_at=now() where tenant_id is null and key='spoke_hole_count' and label is distinct from 'Cantidad de hoyos (rayos)';
update public.spec_definitions set label='Tipo de rayo (con codo o recto)', updated_at=now() where tenant_id is null and key='hub_spoke_head_interface' and label is distinct from 'Tipo de rayo (con codo o recto)';
update public.spec_definitions set label='Tipo de rodamiento', updated_at=now() where tenant_id is null and key='bearing_system' and label is distinct from 'Tipo de rodamiento';
update public.spec_definitions set label='Anclaje del disco (6 pernos o Centerlock)', updated_at=now() where tenant_id is null and key='rotor_mount_type' and label is distinct from 'Anclaje del disco (6 pernos o Centerlock)';
update public.spec_definitions set label='Lleva núcleo o rosca para piñón', updated_at=now() where tenant_id is null and key='hub_drive_receiver_present' and label is distinct from 'Lleva núcleo o rosca para piñón';
update public.spec_definitions set label='Tipo de núcleo', updated_at=now() where tenant_id is null and key='hub_drive_receiver_kind' and label is distinct from 'Tipo de núcleo';
update public.spec_definitions set label='Modelo del núcleo', updated_at=now() where tenant_id is null and key='hub_drive_receiver_reference' and label is distinct from 'Modelo del núcleo';
update public.spec_definitions set label='Círculo de hoyos, brida izquierda (PCD)', updated_at=now() where tenant_id is null and key='flange_pcd_left_mm' and label is distinct from 'Círculo de hoyos, brida izquierda (PCD)';
update public.spec_definitions set label='Círculo de hoyos, brida derecha (PCD)', updated_at=now() where tenant_id is null and key='flange_pcd_right_mm' and label is distinct from 'Círculo de hoyos, brida derecha (PCD)';
update public.spec_definitions set label='Del centro a la brida izquierda', updated_at=now() where tenant_id is null and key='center_to_flange_left_mm' and label is distinct from 'Del centro a la brida izquierda';
update public.spec_definitions set label='Del centro a la brida derecha', updated_at=now() where tenant_id is null and key='center_to_flange_right_mm' and label is distinct from 'Del centro a la brida derecha';
update public.spec_definitions set label='Entre bridas (centro a centro)', updated_at=now() where tenant_id is null and key='hub_flange_to_flange_mm' and label is distinct from 'Entre bridas (centro a centro)';
update public.spec_definitions set label='Diámetro del hoyo del rayo', updated_at=now() where tenant_id is null and key='spoke_hole_diameter_mm' and label is distinct from 'Diámetro del hoyo del rayo';
update public.spec_definitions set label='Dónde se mide el eje', updated_at=now() where tenant_id is null and key='hub_axle_diameter_datum' and label is distinct from 'Dónde se mide el eje';
update public.spec_definitions set label='Modelo del eje pasante incluido', updated_at=now() where tenant_id is null and key='hub_supplied_thru_axle_reference' and label is distinct from 'Modelo del eje pasante incluido';
update public.spec_definitions set label='Mazas de este juego', updated_at=now() where tenant_id is null and key='hub_package_pieces' and label is distinct from 'Mazas de este juego';
update public.spec_templates set form_contract = jsonb_set(form_contract, '{helpers}', coalesce(form_contract->'helpers','{}'::jsonb) || '{"bearing_system": "Sellados: rodamientos de cartucho, se cambian enteros. Bolas sueltas: bolitas con conos y tazas, se ajustan y se engrasan.", "center_to_flange_left_mm": "Desde el centro de la maza (la mitad del ancho entre tuercas) hasta el centro de la brida izquierda. Si el fabricante mide desde la tuerca, convierte antes de escribir; no lo copies tal cual.", "center_to_flange_right_mm": "Desde el centro de la maza hasta el centro de la brida derecha, medido igual que el lado izquierdo.", "flange_pcd_left_mm": "Diámetro del círculo que forman los hoyos de los rayos en la brida izquierda (lado del disco). Se mide de centro de hoyo a centro del hoyo de enfrente.", "flange_pcd_right_mm": "Diámetro del círculo que forman los hoyos de los rayos en la brida derecha (lado del piñón). Se mide de centro de hoyo a centro del hoyo de enfrente.", "hub_axle_diameter_datum": "Escribe dónde se mide: por fuera del eje (lo que se ve en la puntera), en el paso por dentro de la maza, u otro punto que indique el fabricante. Ojo: el perno del cierre rápido no es el eje.", "hub_axle_diameter_mm": "Grosor del eje en el punto que indicaste arriba. Cierre rápido: 9 o 10 mm. Pasante: 12 o 15 mm.", "hub_axle_mount_kind": "Cierre rápido: eje hueco con palanca (9 o 10 mm). Eje pasante: eje grueso de 12 o 15 mm que se enrosca al cuadro. Con tuercas: eje macizo con una tuerca a cada lado.", "hub_drive_receiver_kind": "Núcleo de cassette (HG de Shimano, Micro Spline, XD) o rosca para piñón de rueda libre. Contrapedal es un freno: no dice por sí solo qué piñón acepta.", "hub_drive_receiver_present": "Sólo para mazas traseras. Sí si trae el núcleo para cassette o el hilo para piñón de rosca.", "hub_drive_receiver_reference": "El nombre exacto del núcleo según el fabricante (por ejemplo «HG 8-11v» o «Micro Spline»), si lo publica.", "hub_flange_to_flange_mm": "De centro de una brida al centro de la otra. Es la suma de las dos distancias al centro, no una de ellas.", "hub_old_mm": "De tuerca a tuerca del eje, donde la maza apoya en el cuadro o la horquilla. Lo normal: 100 delante; 135 atrás con cierre rápido; 142 o 148 con eje pasante. Un juego de dos mazas no tiene un solo ancho.", "hub_package_piece_count": "Cuántas mazas trae el juego (normalmente dos: delantera y trasera). Confírmalo con la fuente, no por el título.", "hub_package_pieces": "Sólo lo que viene en la caja: una fila por maza. No es la lista de variantes del fabricante ni una rueda armada.", "hub_package_position": "Qué viene en la caja: una maza delantera, una trasera, o el juego de las dos. Si es el juego, cada maza va en su propia fila más abajo y no se llena un solo ancho ni una sola perforación.", "hub_rotor_mount_present": "Sí si la maza trae dónde afirmar el disco de freno. No si es para freno de llanta (V-brake o caliper).", "hub_spoke_head_interface": "Con codo (J-bend) es el rayo de siempre, con la cabeza doblada que entra por el hoyo de la brida. Recto (straight pull) entra derecho. Si el fabricante no lo dice, déjalo sin confirmar.", "hub_supplied_thru_axle_reference": "El código del eje que viene. Su rosca y su largo son del eje y del cuadro, no de la maza.", "hub_thru_axle_supplied": "Sí sólo si el eje pasante viene en la caja.", "rotor_mount_type": "6 pernos: el disco va apernado con seis pernos Torx. Centerlock: el disco entra estriado y se afirma con un anillo.", "spec_evidence_source": "Pega el link de la página del fabricante, o escribe «manual» o «caja» si lo leíste ahí. Sin fuente, los demás datos quedan como no confirmados.", "spoke_hole_count": "Cuántos rayos lleva la rueda. Lo común es 32 o 36; cuenta los hoyos de una brida.", "spoke_hole_diameter_mm": "Lo que mide el agujero de la brida por donde entra el rayo. Lo normal es 2,5 o 2,6 mm."}'::jsonb), updated_at=now() where tenant_id is null and key='hub' and (form_contract->'helpers') is distinct from (coalesce(form_contract->'helpers','{}'::jsonb) || '{"bearing_system": "Sellados: rodamientos de cartucho, se cambian enteros. Bolas sueltas: bolitas con conos y tazas, se ajustan y se engrasan.", "center_to_flange_left_mm": "Desde el centro de la maza (la mitad del ancho entre tuercas) hasta el centro de la brida izquierda. Si el fabricante mide desde la tuerca, convierte antes de escribir; no lo copies tal cual.", "center_to_flange_right_mm": "Desde el centro de la maza hasta el centro de la brida derecha, medido igual que el lado izquierdo.", "flange_pcd_left_mm": "Diámetro del círculo que forman los hoyos de los rayos en la brida izquierda (lado del disco). Se mide de centro de hoyo a centro del hoyo de enfrente.", "flange_pcd_right_mm": "Diámetro del círculo que forman los hoyos de los rayos en la brida derecha (lado del piñón). Se mide de centro de hoyo a centro del hoyo de enfrente.", "hub_axle_diameter_datum": "Escribe dónde se mide: por fuera del eje (lo que se ve en la puntera), en el paso por dentro de la maza, u otro punto que indique el fabricante. Ojo: el perno del cierre rápido no es el eje.", "hub_axle_diameter_mm": "Grosor del eje en el punto que indicaste arriba. Cierre rápido: 9 o 10 mm. Pasante: 12 o 15 mm.", "hub_axle_mount_kind": "Cierre rápido: eje hueco con palanca (9 o 10 mm). Eje pasante: eje grueso de 12 o 15 mm que se enrosca al cuadro. Con tuercas: eje macizo con una tuerca a cada lado.", "hub_drive_receiver_kind": "Núcleo de cassette (HG de Shimano, Micro Spline, XD) o rosca para piñón de rueda libre. Contrapedal es un freno: no dice por sí solo qué piñón acepta.", "hub_drive_receiver_present": "Sólo para mazas traseras. Sí si trae el núcleo para cassette o el hilo para piñón de rosca.", "hub_drive_receiver_reference": "El nombre exacto del núcleo según el fabricante (por ejemplo «HG 8-11v» o «Micro Spline»), si lo publica.", "hub_flange_to_flange_mm": "De centro de una brida al centro de la otra. Es la suma de las dos distancias al centro, no una de ellas.", "hub_old_mm": "De tuerca a tuerca del eje, donde la maza apoya en el cuadro o la horquilla. Lo normal: 100 delante; 135 atrás con cierre rápido; 142 o 148 con eje pasante. Un juego de dos mazas no tiene un solo ancho.", "hub_package_piece_count": "Cuántas mazas trae el juego (normalmente dos: delantera y trasera). Confírmalo con la fuente, no por el título.", "hub_package_pieces": "Sólo lo que viene en la caja: una fila por maza. No es la lista de variantes del fabricante ni una rueda armada.", "hub_package_position": "Qué viene en la caja: una maza delantera, una trasera, o el juego de las dos. Si es el juego, cada maza va en su propia fila más abajo y no se llena un solo ancho ni una sola perforación.", "hub_rotor_mount_present": "Sí si la maza trae dónde afirmar el disco de freno. No si es para freno de llanta (V-brake o caliper).", "hub_spoke_head_interface": "Con codo (J-bend) es el rayo de siempre, con la cabeza doblada que entra por el hoyo de la brida. Recto (straight pull) entra derecho. Si el fabricante no lo dice, déjalo sin confirmar.", "hub_supplied_thru_axle_reference": "El código del eje que viene. Su rosca y su largo son del eje y del cuadro, no de la maza.", "hub_thru_axle_supplied": "Sí sólo si el eje pasante viene en la caja.", "rotor_mount_type": "6 pernos: el disco va apernado con seis pernos Torx. Centerlock: el disco entra estriado y se afirma con un anillo.", "spec_evidence_source": "Pega el link de la página del fabricante, o escribe «manual» o «caja» si lo leíste ahí. Sin fuente, los demás datos quedan como no confirmados.", "spoke_hole_count": "Cuántos rayos lleva la rueda. Lo común es 32 o 36; cuenta los hoyos de una brida.", "spoke_hole_diameter_mm": "Lo que mide el agujero de la brida por donde entra el rayo. Lo normal es 2,5 o 2,6 mm."}'::jsonb);
commit;
